function go(i){if(busy()||!M.navigate(state,i))return;u.step=i;u.message='';u.wrong=false;u.tail=state.answers.tail||null;u.selected=null;u.readyForWeigh=false;u.harvesting=null;u.batch=null;if(i===5)u.sampleN=4;if(i===9)u.compareN=4;if(i===6)u.standardVisual=state.e.standard;if(i===8)u.discoveryVisual=state.e.histogramShown?1:0;scene.reset();if(i>=4&&i!==14&&i!==15){world.camera.yaw=-.12;world.camera.pitch=.25;}if(i===9)scene.front();if(i===14){scene.reset();world.camera.zoom=innerWidth<=760?1.1:1.35;}persistRender();if(innerWidth<=760){document.querySelector('.visual').scrollIntoView({behavior:'auto',block:'start'});}else{document.querySelector('.workbench').scrollTop=0;}$('task-title').setAttribute('tabindex','-1');$('task-title').focus({preventScroll:true});}
function selectPlot(i){if(busy()||u.step!==1||state.e.harvest.includes(i))return;u.selected=i;u.harvesting=i;u.readyForWeigh=false;u.harvestPhase=0;animate('harvest',1.15,()=>{u.harvestPhase=1;u.readyForWeigh=true;u.harvesting=null;});}
function newPlot(i){if(u.step!==14||busy()||state.e.newHarvest.includes(i))return;u.selected=i;u.harvesting=i;u.harvestPhase=0;animate('harvest',.75,()=>{state.e.newHarvest.push(i);u.harvestPhase=1;u.harvesting=null;});}
function compareN(n){if(u.step!==9||busy())return;u.compareN=Math.max(4,Math.min(100,Math.round(n)));if(!state.e.dfN.includes(u.compareN))state.e.dfN.push(u.compareN);save();$('n-out').value=String(u.compareN);$('comparison-numbers').innerHTML=G.comparisonNumbers(M.convergence(u.compareN));$('df-visited').textContent=dfVisited();document.querySelectorAll('[data-action="compare-n"]').forEach(b=>b.classList.toggle('active',Number(b.dataset.n)===u.compareN));renderDashboard();renderQuiz();renderNavigation();}
function download(){const payload={resource:'玉米产量显著提高了吗',version:4,completed:!!state.completedAt,completedAt:state.completedAt,initialVote:voteLabel(),completedTasks:M.unlocked(state),totalTasks:15,trial:{values:M.values,...main},practice:{values:M.noisy,...practice},attempts:state.attempts};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='玉米试验学习记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function handleAction(e){const b=e.target.closest('[data-action]');if(!b||b.disabled||busy())return;switch(b.dataset.action){
 case 'history':u.historyFrom=state.e.historyStage;animate('history',state.e.historyStage===0?3.6:2.5,()=>{state.e.historyStage=u.historyFrom+1;state.e.history=state.e.historyStage===2;u.historyVisual=state.e.historyStage;});break;
 case 'plot':selectPlot(Number(b.dataset.plot));break;
 case 'weigh':if(u.selected===null||!u.readyForWeigh)return;u.weighPhase=0;animate('weigh',.95,()=>{state.e.harvest.push(u.selected);u.message=`重复${u.selected+1}：${f(M.values[u.selected]*.03)}公斤 ÷ 20m² × 666.67 ≈ ${M.values[u.selected]}公斤/亩。`;u.readyForWeigh=false;});break;
 case 'assume':state.e.nullModel=true;persistRender();break;
 case 'sample':if(!state.e.nullModel)return;u.batch=M.sample(4);u.batchPhase=0;animate('batch',1.05,()=>{state.e.samples.push(u.batch.values);u.batchPhase=1;});break;
 case 'many':for(let i=0;i<40;i++)state.e.samples.push(M.sample(4).values);state.e.samples=state.e.samples.slice(-200);persistRender();break;
 case 'sample-n':u.sampleN=Number(b.dataset.n);if(!state.e.sampleN.includes(u.sampleN))state.e.sampleN.push(u.sampleN);persistRender();break;
 case 'standard':u.standardFrom=state.e.standard===2?0:state.e.standard;u.standardTo=state.e.standard===2?2:state.e.standard+1;u.standardVisual=u.standardFrom;animate('standard',u.standardTo-u.standardFrom>1?6.8:u.standardFrom===0?2.8:4,()=>{state.e.standard=u.standardTo;u.standardVisual=u.standardTo;});break;
 case 'table':state.e.tableOpened=true;u.lookupVisual=0;animate('lookup',1.2,()=>{u.lookupVisual=1;});break;
 case 'table-cell':{const ok=Number(b.dataset.row)===2.5&&Number(b.dataset.col)===0;state.e.tableMatched=ok;state.attempts.push({step:6,choice:`table-${b.dataset.row}-${b.dataset.col}`,correct:ok});u.message=ok?'找到了：行2.5、列0.00，交叉处是0.4938。这个数对应图中0到2.50的蓝色面积。':'我们要找2.50：行取2.5，列取0.00。再看它们的交叉位置。';u.wrong=!ok;persistRender();break;}
 case 'lookup-answer':{const ok=b.dataset.value==='0.0062';state.e.lookup=ok;state.attempts.push({step:6,choice:`area-${b.dataset.value}`,correct:ok});u.message=ok?'对，右半边总面积0.5，减去表中的0.4938，剩下0.0062。标准化让我们共用一张表，所求的概率没有改变。':'表里0.4938只包括0到2.50。我们要的是剩下的右尾，请用0.5减去它。';u.wrong=!ok;persistRender();break;}
 case 'estimate':state.e.estimated=true;persistRender();break;
 case 'variance':if(state.e.runs.length>=1000)return;animate('variance',.5,()=>{state.e.runs.push(M.sample(4).values);state.e.manualRuns++;});break;
 case 'discovery-many':{if(state.e.manualRuns<3)return;const random=M.generator(83091),skip=state.e.runs.length-state.e.manualRuns,remaining=1000-state.e.runs.length;u.pendingGroups=Array.from({length:skip+remaining},()=>M.sample(4,random).values).slice(skip);u.discoveryCommitted=0;animate('discovery',3,()=>{while(u.discoveryCommitted<u.pendingGroups.length)state.e.runs.push(u.pendingGroups[u.discoveryCommitted++]);});break;}
 case 'discovery-tail':{if(!state.e.normalCompared)return;const ok=b.dataset.value==='r';state.e.tailCompared=ok;u.message=ok?'橙色尾部更多：估计的分母也在波动。现在再看看这条分布如何描述。':'请比较±2之外的两种频率。我们要找尾部更多的那一套结果。';u.wrong=!ok;persistRender();break;}
 case 'discovery-histogram':if(state.e.manualRuns<3||state.e.runs.length<1000)return;state.e.histogramShown=true;u.discoveryVisual=0;animate('histogram',1.4,()=>{u.discoveryVisual=1;});break;
 case 'reveal-t':if(!state.e.histogramShown)return;state.e.tRevealed=true;persistRender();break;
 case 'compare-normal':if(!state.e.tRevealed)return;state.e.normalCompared=true;persistRender();break;
 case 'name-t':if(!state.e.tailCompared)return;state.e.gossetShown=true;persistRender();break;
 case 'compare-n':compareN(Number(b.dataset.n));break;
 case 'calculate':state.e.calculated=true;persistRender();break;
 case 'probability':if(state.answers.tail!=='right')return;state.e.probability=true;persistRender();break;
 case 'new-plot':newPlot(Number(b.dataset.plot));break;
 case 'noisy':if(state.e.newHarvest.length<4)return;state.e.noisy=true;persistRender();break;
 case 'summary-answer':M.answer(state,'challenge',b.dataset.value);u.message='';persistRender();break;
 case 'download':download();break;
 case 'review':go(1);break;
 }}
